            # :param, {param} and Flask's <param> / <converter:param> the same
            # way before comparing, to avoid false positives.
            def _normalize(ep: str) -> str:
                return re.sub(r"(:([A-Za-z0-9_]+)|\{([A-Za-z0-9_]+)\}|<(?:[A-Za-z0-9_]+:)?([A-Za-z0-9_]+)>)", "{param}", ep)

