# -*- coding: utf-8 -*-
import json, io, sys, os
os.chdir(sys.argv[1])
P = 'storage/work_packages.json'
w = json.load(io.open(P, encoding='utf-8'))
bp = json.load(io.open('storage/blueprint.json', encoding='utf-8'))
names = [f['name'] for f in bp['lambda_functions']]
by_ep = {}
for f in bp['lambda_functions']:
    for ep in f.get('entry_points') or []:
        m, _, p = ep.partition(' ')
        by_ep[(m.upper(), p)] = f['name']


def norm(p):
    import re
    return re.sub(r'\{[A-Za-z0-9_]+\}|<[A-Za-z0-9_:]+>', '{x}', p)


pkg_of = {}
for fn in bp['lambda_functions']:
    pkg_of[fn['name']] = None
for pkg in w['packages']:
    owner = set()
    for ep in pkg['endpoints']:
        key = (ep['method'].upper(), norm(ep['path']))
        for k, v in by_ep.items():
            if (k[0], norm(k[1])) == key:
                owner.add(v)
    for n in owner:
        pkg_of[n] = pkg['id']

impl = {}
for pkg in w['packages']:
    impl[pkg['id']] = {"functions": [n for n in names if pkg_of[n] == pkg['id']], "dir": {"identity": "identity", "bookings-customers-flights-loyalty-payments": "bookings_flights"}[pkg['id']]}
unassigned = [n for n in names if pkg_of[n] is None]
if unassigned:
    raise SystemExit('functions not covered by any package: %s' % unassigned)
w['impl_packages'] = impl
with io.open(P, 'w', encoding='utf-8') as f:
    json.dump(w, f, ensure_ascii=False, indent=2)
    f.write(u'\n')
print(json.dumps({k: len(v['functions']) for k, v in impl.items()}, ensure_ascii=False))
print('identity dropped endpoints ok; total functions', len(names))

