bad=[]
pat=re.compile(r'([A-Z]+ /[A-Za-z0-9/<>{}_. -]*?)#(responses|business_rules)\[(\d+)\]')
def scan(text,where):
    for m in pat.finditer(text or ''):
        ep=m.group(1).strip(); field=m.group(2); i=int(m.group(3))
        if ep not in idx:
            bad.append((where,'unknown endpoint',ep)); continue
        if i>= idx[ep][field]:
            bad.append((where,ep,field,i,'len=%d'%idx[ep][field]))
for r in bp['metadata']['spec_resolutions']:
    scan(' '.join((r.get('decision') or '')+' '+(r.get('rationale') or ''))+' '+' '.join(r.get('targets') or []), r['issue_id'])
